expected.fmt:
from "@std/testing.ms" import expect_contains, expect_equal, expect_fault

def count_up(limit: Int) -> Int:
    var i = limit - 3
    var steps = 0

    while i < limit:
        steps = steps + 1
        i = i + 1

    return steps

def count_down(limit: Int) -> Int:
    var i = limit + 3
    var steps = 0

    while i > limit:
        steps = steps + 1
        i = i - 1

    return steps

def reset_then_step() -> Int:
    var i = 0

    while i < 1:
        i = 9223372036854775807
        i = i + 1

    return i

def nested_reset(flag: Bool) -> Int:
    var i = 0

    while i < 1:
        if flag:
            i = 9223372036854775807
        i = i + 1

    return i

test "counts reach the extreme without a fault":
    count_up(limit: 9223372036854775807) | try expect_equal(3)
    count_down(limit: -9223372036854775807) | try expect_equal(3)

test "reassigned counter still faults":
    let message = try expect_fault(
        lambda:
            let ignored = reset_then_step()
    )
    message | try expect_contains("Int overflow;")

test "conditionally reassigned counter still faults":
    let message = try expect_fault(
        lambda:
            let ignored = nested_reset(flag: True)
    )
    message | try expect_contains("Int overflow;")
